-- Expand MADEIRA AI healthcare, public services, economy and transport catalogue.
-- Source-listed means present in an official/operator source; it is not a guarantee
-- of live operating status. Timetables and service hours must be checked at source.

on conflict (id) do update set name=excluded.name,category=excluded.category,publisher=excluded.publisher,url=excluded.url,authority=excluded.authority,scope=excluded.scope,update_note=excluded.update_note,last_checked_at=now(),is_active=true;

on conflict (external_key) do update set name=excluded.name,category=excluded.category,description=excluded.description,municipality_id=excluded.municipality_id,phone=excluded.phone,website=excluded.website,source_id=excluded.source_id,source_url=excluded.source_url,verification_status=excluded.verification_status,last_verified_at=now(),is_active=true;
